/**
 * Extract username/handle from social media URL
 * Safe to call with undefined/null; returns empty string when no usable value.
 */
export function extractHandle(rawUrl: string | undefined | null, platform: SocialPlatform): string {
  const url = (rawUrl || '').trim();

  if (!url) {
    return '';
  }

  try {
    const urlObj = new URL(url);
    const pathname = urlObj.pathname;

    // Remove leading/trailing slashes and split
    const parts = pathname.split('/').filter((p) => p.length > 0);

    switch (platform) {
      case 'spotify':
        // spotify.com/artist/{id} or spotify.com/user/{username}
        if (parts.length >= 2 && (parts[0] === 'artist' || parts[0] === 'user')) {
          return `@${parts[1]}`;
        }
        // Return last part if available
        if (parts.length > 0) {
          return `@${parts[parts.length - 1]}`;
        }
        break;

      case 'appleMusic':
        // music.apple.com/us/artist/{name}/{id}
        if (parts.length >= 3 && parts[1] === 'artist') {
          return parts[2].replace(/-/g, ' ');
        }
        // Return last meaningful part
        if (parts.length > 0) {
          const lastPart = parts[parts.length - 1];
          return lastPart.replace(/-/g, ' ');
        }
        break;

      case 'youtube':
        // youtube.com/@username or youtube.com/c/channelname or youtube.com/channel/ID
        if (parts.length >= 1) {
          const lastPart = parts[parts.length - 1];
          return lastPart.startsWith('@') ? lastPart : `@${lastPart}`;
        }
        break;

      case 'x':
        // x.com/username or twitter.com/username
        if (parts.length >= 1) {
          return `@${parts[0]}`;
        }
        break;

      case 'instagram':
        // instagram.com/username
        if (parts.length >= 1) {
          return `@${parts[0]}`;
        }
        break;

      case 'tiktok':
        // tiktok.com/@username
        if (parts.length >= 1) {
          const username = parts[0].startsWith('@') ? parts[0] : `@${parts[0]}`;
          return username;
        }
        break;

      case 'soundcloud':
        // soundcloud.com/username
        if (parts.length >= 1) {
          return `@${parts[0]}`;
        }
        break;

      case 'bandcamp': {
        // yourname.bandcamp.com or bandcamp.com/yourname
        const host = urlObj.hostname.replace(/^www\./, '');

        if (host.endsWith('bandcamp.com')) {
          const subdomain = host.split('.')[0];

          if (subdomain && subdomain !== 'bandcamp') {
            return `@${subdomain}`;
          }
        }

        if (parts.length >= 1) {
          return `@${parts[0]}`;
        }

        break;
      }

      case 'website':
        // For website, use the domain name
        return urlObj.hostname.replace(/^www\./, '');
    }

    // Fallback: if we have path parts, use the last one with @
    if (parts.length > 0) {
      const lastPart = parts[parts.length - 1];
      return lastPart.startsWith('@') ? lastPart : `@${lastPart}`;
    }

    // Final fallback: return the full URL without protocol
    return url.replace(/^https?:\/\//, '').replace(/\/$/, '');
  } catch {
    // If URL parsing fails, return the original URL without protocol
    return url.replace(/^https?:\/\//, '').replace(/\/$/, '');
  }
}
